          <div class="field"><label>Броня</label><select class="select" name="armor">${ARMOR_OPTIONS.map(option => `<option value="${option.id}" ${option.id === user.equipmentSlots?.armor ? 'selected' : ''}>${esc(option.name)}</option>`).join('')}</select></div>
