  const dy = point.y - drag.pointerStart.y;
  const asset = drag.kind === 'asset' ? scene.assets.find(item => item.id === drag.id) : null;
  const token = drag.kind === 'token' ? this.getRuntime(scene.id)?.tokens.find(item => item.id === drag.id) : null;
